import React from 'react';
import { useNavigate } from 'react-router-dom';
import { LogOut } from 'lucide-react';

function Profile({ user, setUser, orders }) {
  const navigate = useNavigate();

  if (!user) {
    navigate('/login');
    return null;
  }

  const handleLogout = () => {
    setUser(null);
    navigate('/');
  };

  return (
    <div className="max-w-4xl mx-auto px-4">
      {/* User Header */}
      <div className="bg-white rounded-2xl shadow-sm border border-gray-100 overflow-hidden mb-8">
        <div className="bg-gradient-to-r from-blue-600 to-blue-800 p-8 flex justify-between items-center text-white">
          <div className="flex items-center space-x-4">
            <div className="w-16 h-16 bg-white rounded-full flex items-center justify-center text-blue-700 text-2xl font-bold shadow-md">
              {user.name.charAt(0)}
            </div>
            <div>
              <h2 className="text-2xl font-bold">{user.name}</h2>
              <p className="text-blue-100">{user.email}</p>
            </div>
          </div>
          <button onClick={handleLogout} className="flex items-center space-x-2 bg-white/20 hover:bg-white/30 px-4 py-2 rounded-lg font-medium">
            <LogOut size={18} />
            <span>Logout</span>
          </button>
        </div>
      </div>

      <h3 className="text-2xl font-bold text-gray-900 mb-6">Order History</h3>
      
      {orders.length === 0 ? (
        <div className="bg-white p-8 rounded-xl shadow-sm border border-gray-100 text-center text-gray-500">
          You haven't placed any orders yet.
        </div>
      ) : (
        <div className="space-y-6">
          {orders.map((order) => (
            <div key={order.id} className="bg-white rounded-xl shadow-sm border border-gray-100 p-6">
              <div className="flex justify-between items-center border-b border-gray-100 pb-4 mb-4">
                <div>
                  <span className="text-sm font-medium text-gray-500 block mb-1">Order #{order.id}</span>
                  <span className="font-bold text-gray-900">{order.date}</span>
                </div>
                <div className="text-right">
                  <span className="block text-sm font-medium text-green-600 bg-green-50 px-3 py-1 rounded-full mb-1">Processing</span>
                  <div className="font-extrabold text-gray-900">${order.total.toFixed(2)}</div>
                </div>
              </div>
              
              <div className="space-y-3">
                {order.items.map((item, idx) => (
                  <div key={idx} className="flex justify-between text-sm">
                    <span className="text-gray-700 font-medium">• {item.name}</span>
                    <span className="text-gray-500">${item.price}</span>
                  </div>
                ))}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

export default Profile;
